/**
 * Auth Middleware — JWT verification, token refresh, and request ID tracking.
 * Generated by BackendForge
 */

const jwt = require('jsonwebtoken');
const { env } = require('../config/env');
const { v4: uuidv4 } = require('uuid');
const { User } = require('../models');

/**
 * Adds a unique request ID to every request.
 */
const requestIdMiddleware = (req, res, next) => {
  req.requestId = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', req.requestId);
  next();
};

/**
 * Authenticate user via JWT token.
 * Attaches req.user with user data.
 */
const authenticate = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({
        success: false,
        message: 'Access denied. No token provided.',
        code: 'NO_TOKEN',
      });
    }

    const token = authHeader.split(' ')[1];

    // Check if token is blacklisted (logged out)
    const { getRedisClient } = require('../config/redis');
    const redis = getRedisClient();
    if (redis) {
      const isBlacklisted = await redis.get(`bl_${token}`);
      if (isBlacklisted) {
        return res.status(401).json({
          success: false,
          message: 'Token has been revoked. Please login again.',
          code: 'TOKEN_REVOKED',
        });
      }
    }

    const decoded = jwt.verify(token, env.JWT_SECRET);

    const user = await User.findByPk(decoded.userId);

    if (!user) {
      return res.status(401).json({
        success: false,
        message: 'User not found. Token may be invalid.',
        code: 'USER_NOT_FOUND',
      });
    }

    if (!user.isActive) {
      return res.status(403).json({
        success: false,
        message: 'Account has been deactivated.',
        code: 'ACCOUNT_DEACTIVATED',
      });
    }

    req.user = user;
    req.userId = decoded.userId;
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({
        success: false,
        message: 'Token expired. Please refresh or login again.',
        code: 'TOKEN_EXPIRED',
      });
    }
    if (error.name === 'JsonWebTokenError') {
      return res.status(401).json({
        success: false,
        message: 'Invalid token.',
        code: 'INVALID_TOKEN',
      });
    }
    return res.status(500).json({ success: false, message: 'Authentication error.' });
  }
};

/**
 * Require specific role(s).
 * Usage: authorize('admin', 'superadmin')
 */
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ success: false, message: 'Not authenticated.' });
    }
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        success: false,
        message: `Access denied. Required role(s): ${roles.join(', ')}`,
        code: 'INSUFFICIENT_ROLE',
      });
    }
    next();
  };
};

/**
 * Optional authentication — doesn't fail if no token, but attaches user if present.
 */
const optionalAuth = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      const token = authHeader.split(' ')[1];
      const decoded = jwt.verify(token, env.JWT_SECRET);
      req.user = await User.findByPk(decoded.userId);
      req.userId = decoded.userId;
    }
  } catch {
    // Silently ignore auth errors for optional auth
  }
  next();
};

module.exports = { requestIdMiddleware, authenticate, authorize, optionalAuth };
